from collections import defaultdict

def read_ints():
    return list(map(int, input().split()))

def find_minimum_atoms(n, subsets):
    from itertools import combinations

    # Create a graph where nodes are elements and edges are subsets
    graph = defaultdict(list)
    for i, subset in enumerate(subsets):
        for elem in subset:
            graph[elem].append(i)

    # Find the minimum set cover
    covered = set()
    atoms = []
    while covered != set(range(n)):
        best_set = None
        best_score = float('inf')
        for subset in subsets:
            score = len(set(subset) - covered)
            if score < best_score:
                best_score = score
                best_set = subset
        atoms.append(best_set)
        covered.update(best_set)

    return len(atoms)

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n, m = read_ints()
        subsets = []
        for _ in range(m):
            vi, *si = read_ints()
            subsets.append(si)
        results.append(find_minimum_atoms(n, subsets))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
